_ADMITRUN_AGENT_PROFILE = validate.text(64, '^[a-z][a-z0-9-]{0,63}$', None)
_ADMITRUN_SKILLS = validate.sequence(32, validate.text(64, '^[a-z][a-z0-9-]{0,63}$', None))
_ADMITRUN_REQUESTED_CAPABILITIES = validate.sequence(64, validate.text(512, '^[a-z][a-z0-9_]{0,15}\\.[a-z][a-z0-9_]{0,31}:[A-Za-z0-9._/*:@+~<>-]{1,384}(\\?[A-Za-z0-9_=,&.*/-]{1,96})?$', None))


@dataclass(frozen=True, slots=True, kw_only=True)
class AdmitRun:
    """Asks the kernel to admit a run and mint its authority. `requested_capabilities` is a
    request, not an assertion: the kernel intersects it with the agent profile, the
    skills, the parent grant and the profile ceiling, and returns what survived
    (`CAPABILITIES.md` §4, `mint` step 5). Asking for more is not an error, because an
    error invites a retry loop; it yields less, and the difference is reported. There is
    no `mode`, `profile`, `workspace_sensitivity`, `taint` or `privacy_class` field.
    Those are policy inputs, and ADR-0028 makes every policy input kernel-derived: a
    field here would be the runtime asserting one.
    """

    agent_profile: str
    """Which agent profile the run is for. The kernel resolves it to the profile's declared
    capabilities; an unknown name is a denial, not a protocol error.
    """
    skills: list[str]
    """The skills to activate. Skills only ever narrow."""
    requested_capabilities: list[str]
    """The capabilities the run would like. May exceed what it can have."""

    @classmethod
    def decode(cls, value: JsonValue, cx: Cx) -> Self:
        obj = validate.expect_object(value, cx)
        known, _extensions = validate.partition(obj, ('agent_profile', 'skills', 'requested_capabilities'), False, cx)
        agent_profile_ = validate.take_required(known, 'agent_profile', cx, _ADMITRUN_AGENT_PROFILE)
        skills_ = validate.take_required(known, 'skills', cx, _ADMITRUN_SKILLS)
        requested_capabilities_ = validate.take_required(known, 'requested_capabilities', cx, _ADMITRUN_REQUESTED_CAPABILITIES)
        return cls(agent_profile=agent_profile_, skills=skills_, requested_capabilities=requested_capabilities_)

    def encode(self) -> dict[str, JsonValue]:
        out: dict[str, JsonValue] = {}
        out['agent_profile'] = self.agent_profile
        skills_out: list[JsonValue] = list(self.skills)
        out['skills'] = skills_out
        requested_capabilities_out: list[JsonValue] = list(self.requested_capabilities)
        out['requested_capabilities'] = requested_capabilities_out
        return out


_AUTHORITYQUERY_PROPOSED = validate.text(512, '^[a-z][a-z0-9_]{0,15}\\.[a-z][a-z0-9_]{0,31}:[A-Za-z0-9._/*:@+~<>-]{1,384}(\\?[A-Za-z0-9_=,&.*/-]{1,96})?$', None)


@dataclass(frozen=True, slots=True, kw_only=True)
class AuthorityQuery:
    """Asks what a run may do, and optionally whether one specific action is permitted.
    Read-only in both shapes. It reports authority and grants none, touches no resource,
    reserves nothing and performs no effect: it is the question M3 exists to answer,
    asked without doing anything about the answer.
    """

    proposed: str | None = None
    """A proposed action, in the kernel's capability grammar. When absent the response
    reports effective authority only. When present, the response is a `decision` for
    exactly this action **only if** the authority can construct the complete canonical
    action it names; otherwise it is `direwolf.authority.refused` with
    `NO_CANONICAL_ACTION`. Through M3e that is every proposal, because capability text
    alone never determines one (ADR-0040).
    """

    @classmethod
    def decode(cls, value: JsonValue, cx: Cx) -> Self:
        obj = validate.expect_object(value, cx)
        known, _extensions = validate.partition(obj, ('proposed',), False, cx)
        proposed_ = validate.take_optional(known, 'proposed', cx, _AUTHORITYQUERY_PROPOSED)
        return cls(proposed=proposed_)

    def encode(self) -> dict[str, JsonValue]:
        out: dict[str, JsonValue] = {}
        if self.proposed is not None:
            out['proposed'] = self.proposed
        return out


_AUTHORITYREFUSAL_OPERATION = validate.enumeration(('ACQUIRE_LEASE', 'RELEASE_LEASE', 'HEARTBEAT', 'ADMIT_RUN', 'RELEASE_RUN', 'QUERY_AUTHORITY'))
_AUTHORITYREFUSAL_REASON = validate.enumeration(('STALE_EPOCH', 'LEASE_HELD', 'IDEMPOTENCY_CONFLICT', 'ADMISSION_ENDED', 'UNKNOWN_AGENT_PROFILE', 'UNKNOWN_RUN', 'NO_CANONICAL_ACTION'))
_AUTHORITYREFUSAL_PAIRING = {
    'ACQUIRE_LEASE': ('LEASE_HELD',),
    'RELEASE_LEASE': ('STALE_EPOCH',),
    'HEARTBEAT': ('STALE_EPOCH',),
    'ADMIT_RUN': ('STALE_EPOCH', 'IDEMPOTENCY_CONFLICT', 'ADMISSION_ENDED', 'UNKNOWN_AGENT_PROFILE'),
    'RELEASE_RUN': ('STALE_EPOCH',),
    'QUERY_AUTHORITY': ('STALE_EPOCH', 'UNKNOWN_RUN', 'NO_CANONICAL_ACTION'),
}


@dataclass(frozen=True, slots=True, kw_only=True)
class AuthorityRefusal:
    """The authority declined to act on a well-formed request. **Three different things a
    caller must be able to tell apart**, and this is the middle one: *
    `direwolf.protocol.error` — the bytes did not form a valid message. Nothing was
    evaluated because nothing arrived. The remedy is to fix the message. * **this** —
    the message was valid and the authority's own state does not permit the operation to
    be attempted. No policy ran, no capability was consulted. The remedy is named by
    `reason` and is usually to re-acquire a lease, admit a run, or stop retrying. *
    `direwolf.authority.effective` carrying a `DENY` decision — both gates of ADR-0006
    ran against real state and refused. The remedy is to ask for less, or to change
    policy. Merging any two of those to save a message type would leave a caller unable
    to choose between three different remedies, and the failure mode of guessing is a
    retry loop against a refusal that will never change. **Two fields, and no third.**
    There is no `detail` string, no `hint`, no map: `ProtocolErrorPayload` carries a
    detail because a malformed message needs a human to repair *a message*, whereas a
    refusal needs the caller to take one of five known actions. Every byte beyond the
    reason is a byte the authority tells a caller about state the caller could not
    otherwise see — which is how a refusal becomes an oracle. `STALE_EPOCH` in
    particular does **not** carry the kernel's current epoch: handing a fenced runtime
    the one value it needs to un-fence itself would undo the fencing.
    """

    operation: str
    """Which operation was refused. Redundant with `causation_id` for a caller that still
    has the request; not redundant for an audit record, and it is what closes the
    pairing below.
    """
    reason: str
    """Why. Closed, and narrower still per operation."""

    @classmethod
    def decode(cls, value: JsonValue, cx: Cx) -> Self:
        obj = validate.expect_object(value, cx)
        known, _extensions = validate.partition(obj, ('operation', 'reason'), False, cx)
        operation_ = validate.take_required(known, 'operation', cx, _AUTHORITYREFUSAL_OPERATION)
        reason_ = validate.take_required(known, 'reason', cx, _AUTHORITYREFUSAL_REASON)
        validate.paired('operation', operation_, 'reason', reason_, _AUTHORITYREFUSAL_PAIRING, cx)
        return cls(operation=operation_, reason=reason_)

    def encode(self) -> dict[str, JsonValue]:
        out: dict[str, JsonValue] = {}
        out['operation'] = self.operation
        out['reason'] = self.reason
        return out


