_PROTOCOLERRORPAYLOAD_CODE = validate.enumeration(('PROTOCOL_FRAME_EMPTY', 'PROTOCOL_FRAME_TOO_LARGE', 'PROTOCOL_FRAME_TRUNCATED', 'PROTOCOL_CONTENT_TYPE_UNSUPPORTED', 'PROTOCOL_INVALID_UTF8', 'PROTOCOL_INVALID_JSON', 'PROTOCOL_DUPLICATE_KEY', 'PROTOCOL_MAX_DEPTH_EXCEEDED', 'PROTOCOL_NUMBER_OUT_OF_DOMAIN', 'PROTOCOL_VERSION_UNSUPPORTED', 'PROTOCOL_UNKNOWN_OPERATION', 'PROTOCOL_SCHEMA_VIOLATION'))
_PROTOCOLERRORPAYLOAD_VIOLATION = validate.enumeration(('UNKNOWN_FIELD', 'MISSING_FIELD', 'FORBIDDEN_FIELD', 'WRONG_TYPE', 'NULL_NOT_ALLOWED', 'OUT_OF_RANGE', 'TOO_LONG', 'INVALID_FORMAT', 'UNKNOWN_VARIANT', 'TOO_MANY_ITEMS', 'INCONSISTENT'))
