@dataclass(frozen=True, slots=True, kw_only=True)
class ProtocolErrorPayload:
    """The message did not decode. This is **not** a policy denial: nothing was evaluated,
    because there was nothing well-formed to evaluate.
    """

    code: str
    """Stable error code."""
    violation: str | None = None
    """Finer classification for schema and version failures."""
    path: str | None = None
    """JSON Pointer to the failing location."""
    detail: str
    """Short explanation. Informational; bounded."""
    supported: VersionSpan | None = None
    """For version failures, the range the receiver supports."""

    @classmethod
    def decode(cls, value: JsonValue, cx: Cx) -> Self:
        obj = validate.expect_object(value, cx)
        known, _extensions = validate.partition(obj, ('code', 'violation', 'path', 'detail', 'supported'), False, cx)
        code_ = validate.take_required(known, 'code', cx, _PROTOCOLERRORPAYLOAD_CODE)
        violation_ = validate.take_optional(known, 'violation', cx, _PROTOCOLERRORPAYLOAD_VIOLATION)
        path_ = validate.take_optional(known, 'path', cx, _PROTOCOLERRORPAYLOAD_PATH)
        detail_ = validate.take_required(known, 'detail', cx, _PROTOCOLERRORPAYLOAD_DETAIL)
        supported_ = validate.take_optional(known, 'supported', cx, VersionSpan.decode)
        return cls(code=code_, violation=violation_, path=path_, detail=detail_, supported=supported_)

    def encode(self) -> dict[str, JsonValue]:
        out: dict[str, JsonValue] = {}
        out['code'] = self.code
        if self.violation is not None:
            out['violation'] = self.violation
        if self.path is not None:
            out['path'] = self.path
        out['detail'] = self.detail
        if self.supported is not None:
            out['supported'] = self.supported.encode()
        return out


