@dataclass(frozen=True, slots=True, kw_only=True)
class ToolRefusalV3:
    """A version-3 tool operation the authority would not attempt. Nothing was performed
    and no broker was contacted.
    """

    operation: str
    """Which operation."""
    reason: str
    """Why."""

    @classmethod
    def decode(cls, value: JsonValue, cx: Cx) -> Self:
        obj = validate.expect_object(value, cx)
        known, _extensions = validate.partition(obj, ('operation', 'reason'), False, cx)
        operation_ = validate.take_required(known, 'operation', cx, _TOOLREFUSALV3_OPERATION)
        reason_ = validate.take_required(known, 'reason', cx, _TOOLREFUSALV3_REASON)
        validate.paired('operation', operation_, 'reason', reason_, _TOOLREFUSALV3_PAIRING, cx)
        return cls(operation=operation_, reason=reason_)

    def encode(self) -> dict[str, JsonValue]:
        out: dict[str, JsonValue] = {}
        out['operation'] = self.operation
        out['reason'] = self.reason
        return out


_TOOLRESULT_INVOCATION_ID = validate.identifier('inv')


@dataclass(frozen=True, slots=True, kw_only=True)
class ToolResult:
    """An invocation the authority allowed, the broker performed on the object that was
    checked, and the authority recorded -- in that order.
    """

    invocation_id: str
    """The authority's id for this invocation."""
    action: ToolAction
    """The canonical action that was decided and performed."""
    decision: ToolDecision
    """Both gates' decision."""
    fs_read: FsReadResult
    """The `fs.read` result."""

    @classmethod
    def decode(cls, value: JsonValue, cx: Cx) -> Self:
        obj = validate.expect_object(value, cx)
        known, _extensions = validate.partition(obj, ('invocation_id', 'action', 'decision', 'fs_read'), False, cx)
        invocation_id_ = validate.take_required(known, 'invocation_id', cx, _TOOLRESULT_INVOCATION_ID)
        action_ = validate.take_required(known, 'action', cx, ToolAction.decode)
        decision_ = validate.take_required(known, 'decision', cx, ToolDecision.decode)
        fs_read_ = validate.take_required(known, 'fs_read', cx, FsReadResult.decode)
        return cls(invocation_id=invocation_id_, action=action_, decision=decision_, fs_read=fs_read_)

    def encode(self) -> dict[str, JsonValue]:
        out: dict[str, JsonValue] = {}
        out['invocation_id'] = self.invocation_id
        out['action'] = self.action.encode()
        out['decision'] = self.decision.encode()
        out['fs_read'] = self.fs_read.encode()
        return out


